1	import { describe, it, expect } from "vitest";
2	import { runScenario } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office", () => {
5	  // --- Quote: simplest case and single main items -------------------------
6	  it("empty item list → premium 5 G (only the processing fee)", () => {
7	    const result = runScenario({
8	      customer: { yearsWithMHPCO: 0 },
9	      steps: [{ op: "quote", items: [] }],
10	    });
11	
12	    expect(result).toEqual({ results: [{ premium: 5 }] });
13	  });
14	  it.todo("plain sword (base 100 G) for a newcomer → premium 115 G (100 + 10 first insurance + 5 fee)");
15	  it.todo("plain amulet (base 60 G) for a newcomer → premium 71 G (60 + 6 first insurance + 5 fee)");
16	  it.todo("plain staff (base 80 G) for a newcomer → premium 93 G (80 + 8 first insurance + 5 fee)");
17	  it.todo("plain potion (base 40 G) for a newcomer → premium 49 G (40 + 4 first insurance + 5 fee)");
18	
19	  // --- Components and blocks of 3 alike -----------------------------------
20	  it.todo("1 rune → 25 G base premium");
21	  it.todo("2 runes → 50 G base premium");
22	  it.todo("3 runes → 60 G base premium (block applies)");
23	  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
24	  it.todo("7 runes → 175 G base premium");
25	  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
26	  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
27	
28	  // --- Item-specific modifiers --------------------------------------------
29	  it.todo("cursed sword adds a 50 % surcharge on that item's base premium (100 → 150)");
30	  it.todo("sword with exactly enchantment 5 → high-enchantment surcharge applies (100 → 130)");
31	  it.todo("sword with enchantment 4 → no high-enchantment surcharge (100 → 100)");
32	  it.todo("cursed sword with exactly enchantment 5 → both surcharges apply (100 → 180)");
33	
34	  // --- Policy-wide modifiers ----------------------------------------------
35	  it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
36	  it.todo("customer with 1 year with MHPCO → no loyalty discount");
37	  it.todo("each item in a quote carries a 10 % first insurance surcharge regardless of customer history");
38	  it.todo("second quote in a scenario receives a 15 % follow-up contract discount");
39	
40	  // --- Modifier scope on multi-item policies ------------------------------
41	  it.todo("cursed sword + plain amulet → policy base 160 G, curse adds 50 G (only the sword's base) → 210 G before further modifiers and fee");
42	
43	  // --- Rounding in the MHPCO's favour --------------------------------------
44	  it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
45	  it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");
46	  it.todo("intermediate amounts are kept as fractions; only the final amount is rounded");
47	
48	  // --- Integration examples ------------------------------------------------
49	  it.todo("newcomer with a cursed sword (steel, enchantment 3) → premium 165 G");
50	  it.todo("3-year customer's second quote, cursed sword enchantment 7 → premium 160 G");
51	
52	  // --- Insurance sum and cap ----------------------------------------------
53	  it.todo("policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
54	  it.todo("policy covering two swords → insurance sum 2000 G, cap 4000 G");
55	  it.todo("policy covering a sword and 3 runes → insurance sum 1750 G (block affects premium only), cap 3500 G");
56	  it.todo("cursed sword (premium 165 G) → cap 2000 G, based on the unmodified insurance value");
57	
58	  // --- Claim: standard reimbursement ---------------------------------------
59	  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
60	  it.todo("damage to a rune (no enchantment, no material), damage 200 G → payout 100 G");
61	
62	  // --- Claim: special clauses ----------------------------------------------
63	  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % then deductible)");
64	  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement then deductible)");
65	  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins, then deductible)");
66	  it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G");
67	
68	  // --- Claim: deductible per damage event ----------------------------------
69	  it.todo("dragon attack damages sword (500 G) and amulet (300 G) → payout 600 G (deductible once per damaged item)");
70	  it.todo("dragon attack damages both of two insured swords → each damage entry gets its own deductible");
71	  it.todo("damage amount below the deductible does not produce a negative payout");
72	
73	  // --- Claim: cap ----------------------------------------------------------
74	  it.todo("sword policy (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
75	  it.todo("sword policy, second successive claim of 1500 G → payout 600 G, remainingCap 0 G (reduced to remaining cap)");
76	
77	  // --- Error cases ---------------------------------------------------------
78	  it.todo("quote with an unknown item type (broomstick) → error");
79	  it.todo("claim referencing an item not part of the policy (amulet when only a sword is insured) → error");
80	  it.todo("claim referencing an item with an unknown type → error");
81	  it.todo("claim with more damage entries of a type than the policy covers (two sword damages, one sword insured) → error");
82	  it.todo("claim with a damage entry of amount -200 → error");
83	
84	  // --- CLI -----------------------------------------------------------------
85	  it.todo("CLI reads a scenario from stdin and writes {results: [...]} to stdout in step order");
86	  it.todo("CLI on the schema example → results [{premium: ...}, {payout: 100, remainingCap: ...}]");
87	  it.todo("CLI exits with a non-zero status code and writes an error to stderr for an unknown item type, with no results on stdout");
88	  it.todo("CLI exits with a non-zero status code and writes an error to stderr for an invalid claim");
89	});
